SET NAMES utf8mb4;
DROP TABLE IF EXISTS recipe_ingredients;
DROP TABLE IF EXISTS gallery_images;
DROP TABLE IF EXISTS messages;
DROP TABLE IF EXISTS recipes;
DROP TABLE IF EXISTS ingredients;
DROP TABLE IF EXISTS categories;
DROP TABLE IF EXISTS users;

CREATE TABLE categories (id INT PRIMARY KEY, name VARCHAR(120) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE recipes (id INT PRIMARY KEY, name VARCHAR(160) NOT NULL, category_id INT NOT NULL, created_at DATE NULL, published_at DATE NULL, summary TEXT NOT NULL, difficulty VARCHAR(20) NOT NULL, prep_minutes INT NOT NULL, featured_image TEXT NOT NULL, CONSTRAINT fk_recipes_category FOREIGN KEY (category_id) REFERENCES categories(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ingredients (id INT PRIMARY KEY, name VARCHAR(160) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE recipe_ingredients (recipe_id INT NOT NULL, ingredient_id INT NOT NULL, amount VARCHAR(30) NULL, unit VARCHAR(80) NULL, CONSTRAINT fk_ri_recipe FOREIGN KEY (recipe_id) REFERENCES recipes(id), CONSTRAINT fk_ri_ingredient FOREIGN KEY (ingredient_id) REFERENCES ingredients(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, family_name VARCHAR(120) NOT NULL, given_name VARCHAR(120) NOT NULL, username VARCHAR(80) NOT NULL UNIQUE, email VARCHAR(180) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE gallery_images (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(160) NOT NULL, description TEXT NULL, filename VARCHAR(255) NULL, external_url TEXT NULL, uploaded_by_user_id INT NULL, created_at DATETIME NOT NULL, CONSTRAINT fk_gallery_user FOREIGN KEY (uploaded_by_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE messages (id INT AUTO_INCREMENT PRIMARY KEY, sender_name VARCHAR(160) NOT NULL, sender_email VARCHAR(180) NOT NULL, subject VARCHAR(180) NOT NULL, body TEXT NOT NULL, user_id INT NULL, created_at DATETIME NOT NULL, CONSTRAINT fk_messages_user FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

